@ VPy — ARM Thumb2 target (UVM2 / Ultimate Vectrex Multicart 2)
@ Game: pang
@ Generated by vpy_codegen uvm2 backend
@ Assemble with: arm-none-eabi-as -mthumb -mcpu=cortex-m33 game.s -o game.o

.syntax unified
.cpu cortex-m33
.fpu fpv5-sp-d16
.thumb

@ === ARM Cortex-M vector table (required by UVM2 firmware) ===
.section .vectors, "ax"
.align 2
.word 0x20082000        @ Initial SP = top of RP2350 SRAM (520KB)
.word game_main + 1     @ Reset_Handler (Thumb bit set)
.word _uvm2_default_handler @ NMI
.word _uvm2_default_handler @ HardFault
.word _uvm2_default_handler @ MemManage
.word _uvm2_default_handler @ BusFault
.word _uvm2_default_handler @ UsageFault
.word _uvm2_default_handler @ SecureFault
.word _uvm2_default_handler @ _reserved7
.word _uvm2_default_handler @ _reserved8
.word _uvm2_default_handler @ _reserved9
.word _uvm2_default_handler @ SVC
.word _uvm2_default_handler @ DebugMon
.word _uvm2_default_handler @ _reserved11
.word _uvm2_default_handler @ PendSV
.word _uvm2_default_handler @ SysTick
.rept 52
.word _uvm2_default_handler
.endr

.thumb_func
_uvm2_default_handler:
    b _uvm2_default_handler

@ --- VPy runtime RAM (RP2350 SRAM) ---
.equ TMPVAL,              0x2007F000  @ 32-bit arithmetic temporary
.equ TMPPTR,              0x2007F004  @ pointer temporary
.equ TMPPTR2,             0x2007F008  @ second pointer temporary
.equ VAR_ARG0,            0x2007F00C  @ function argument 0
.equ VAR_ARG1,            0x2007F010  @ function argument 1
.equ VAR_ARG2,            0x2007F014  @ function argument 2
.equ VAR_ARG3,            0x2007F018  @ function argument 3
.equ VAR_ARG4,            0x2007F01C  @ function argument 4
.equ RESULT,              0x2007F020  @ function return value
.equ BEEP_FRAMES_LEFT,    0x2007F024  @ non-blocking beep counter
.equ VIA_WRITE_ADDR,      0x2007F028  @ scratch for bus_write address
.equ VIA_WRITE_DATA,      0x2007F02C  @ scratch for bus_write data
.equ _dv3d_cos,           0x2007F030  @ 3D cos offsets: cos_ax, cos_ay, cos_az (3 bytes)
.equ _dv3d_tmp,           0x2007F034  @ 3D vertex raw coords: rx, ry, rz (3 bytes)
.equ _dv3d_sm,            0x2007F038  @ 3D rotation intermediates: t0, y1, z1, x2 (4 bytes)
.equ _dv3d_cur,           0x2007F03C  @ 3D current beam pos: cur_x, cur_y (2 bytes)
.equ _dv3d_fst,           0x2007F03E  @ 3D first vertex of path: first_x, first_y (2 bytes)
.equ _dv3d_vbuf,          0x2007F040  @ 3D rotated vertex cache: sx,sy pairs (254 bytes max)
.equ VPY_ANIM_STATE_BUF,  0x2007F13E  @ animation frame_idx(u8) at +0, ticks_left(u8) at +1
.equ RAND_SEED,           0x2007F140  @ LCG random number seed
.equ BTN_STATE_J1,        0x2007F144  @ cached VIA Port B (J1 buttons, bits 4-7 active-low)
.equ BTN_STATE_J2,        0x2007F148  @ cached PSG reg 14 (J2 buttons, bits 0-3 active-low)
.equ CAMERA_X,            0x2007F14C  @ camera X offset (used by show_level)
.equ CAMERA_Y,            0x2007F150  @ camera Y offset
.equ TEXT_SIZE,           0x2007F154  @ text scale factor (1=normal, 2=double, ...)
.equ TEXT_COLOR,          0x2007F158  @ text intensity (0-127)
.equ LEVEL_DATA_PTR,      0x2007F15C  @ pointer to loaded level ROM data
.equ DBGVAL,              0x2007F160  @ debug_print last written value
.equ PRINT_BEAM_X,        0x2007F164  @ beam X shadow during print_text
.equ PRINT_BEAM_Y,        0x2007F168  @ beam Y shadow during print_text
.equ PSG_MUSIC_PTR,       0x2007F16C  @ pointer to current music event in ROM
.equ PSG_MUSIC_START,     0x2007F170  @ pointer to loop-start event
.equ PSG_IS_PLAYING,      0x2007F174  @ 1 = music playing
.equ PSG_DELAY_FRAMES,    0x2007F178  @ frames remaining before next music event
.equ PSG_SFX_PTR,         0x2007F17C  @ pointer to current SFX event in ROM
.equ PSG_SFX_ACTIVE,      0x2007F180  @ 1 = SFX playing
.equ PSG_SFX_DELAY,       0x2007F184  @ frames remaining before next SFX event
.equ LEVEL_GP_COUNT,      0x2007F188  @ number of active GP objects
.equ LEVEL_GP_BUF,        0x2007F18C  @ level GP mutable buffer (32 obj × 8 bytes = 256 bytes)
.equ SCROLL_LIMIT_LEFT,   0x2007F28C  @ camera scroll limit: left world X
.equ SCROLL_LIMIT_RIGHT,  0x2007F290  @ camera scroll limit: right world X
.equ SCROLL_LIMIT_TOP,    0x2007F294  @ camera scroll limit: top world Y
.equ SCROLL_LIMIT_BOTTOM, 0x2007F298  @ camera scroll limit: bottom world Y
.equ NOTE_STATE,          0x2007F29C  @ note engine state: 3 channels × 32 bytes each
.equ PSG_MIXER_SHADOW,    0x2007F2FC  @ shadow of AY R7 mixer register (0x3F = all disabled)
.equ VPY_MOVE_X,          0x2007F300  @ last MOVE X position (added to DRAW_LINE x0/x1)
.equ VPY_MOVE_Y,          0x2007F304  @ last MOVE Y position (added to DRAW_LINE y0/y1)
.equ ENEMY_COUNT_ARM,     0x2007F308  @ active enemy count
.equ ENEMY_POOL_ARM,      0x2007F30C  @ enemy pool: 8 slots × 32 bytes
.equ J1_AXIS_X,           0x2007F40C  @ cached J1 X axis (-127..127), updated each WAIT_RECAL
.equ J1_AXIS_Y,           0x2007F410  @ cached J1 Y axis (-127..127), updated each WAIT_RECAL
.equ J2_AXIS_X,           0x2007F414  @ cached J2 X axis (-127..127), updated each WAIT_RECAL
.equ J2_AXIS_Y,           0x2007F418  @ cached J2 Y axis (-127..127), updated each WAIT_RECAL
.equ ENEMY_STATE_ARM,     0x2007F41C  @ enemy state per slot: 8 × i32
.equ VPY_PLAYER_ANIM_STATE, 0x2007F43C  @ player animation state: frame_idx(u8)+ticks_left(u8)
.equ WANDER_SCRATCH_ARM,  0x2007F440  @ wander AI scratch: 8 slots x 4 bytes (scratch_a|target_x)
.equ USER_RAM_START,      0x2007F460  @ user variables begin here

@ --- VIA 6522 registers (Vectrex bus addresses) ---
.equ VIA_BASE,       0xD000
.equ VIA_PORT_B,     0xD000
.equ VIA_PORT_A,     0xD001
.equ VIA_DDR_B,      0xD002
.equ VIA_DDR_A,      0xD003
.equ VIA_T1C_L,      0xD004
.equ VIA_T1C_H,      0xD005
.equ VIA_T1L_L,      0xD006
.equ VIA_T1L_H,      0xD007
.equ VIA_SR,         0xD00A
.equ VIA_ACR,        0xD00B
.equ VIA_PCR,        0xD00C
.equ VIA_IFR,        0xD00D
.equ VIA_IER,        0xD00E

@ VIA Port B bits
.equ PB_MUX,         0x01
.equ PB_BEAM,        0x08
.equ PB_ZPULSE,      0x10

@ VIA ACR / PCR values
.equ ACR_SR_SHIFT,   0x18
.equ PCR_BEAM_OFF,   0xCE
.equ PCR_BEAM_ON,    0xDE
.equ T1_STANDARD,    0x7F

@ --- RP2350 SIO (GPIO bit-bang) — UVM2 pinout ---
@ Source: Ralf (UVM2 firmware author), 2026-04-16
.equ SIO_BASE,       0xD0000000
.equ SIO_GPIO_OUT,   0xD0000010
.equ SIO_GPIO_SET,   0xD0000014
.equ SIO_GPIO_CLR,   0xD0000018
.equ SIO_GPIO_OE_SET,0xD0000024
.equ SIO_GPIO_OE_CLR,0xD0000028
.equ SIO_GPIO_IN,    0xD0000004

@ UVM2 GPIO pin assignments
.equ PIN_D0,         0          @ D0
.equ PIN_D7,         7          @ D7
.equ DATA_MASK,      0x000000FF  @ GPIO 0-7
.equ PIN_A0,         8          @ A0  (GPIO8)
.equ PIN_A13,        21         @ A13 (GPIO21)
.equ ADDR_MASK,      0x003FFF00  @ GPIO 8-21 = A0-A13
.equ PIN_PB6,        22         @ VIA Port B bit 6 (beam control)
.equ PIN_NIRQ,       23         @ /IRQ
.equ PIN_A14,        24         @ A14 (GPIO24)
.equ PIN_A15,        25         @ A15
.equ PIN_RW,         26         @ R/W (1=read, 0=write)
.equ PIN_NHALT,      27         @ /HALT — assert LOW to take bus
.equ PIN_NNMI,       29         @ /NMI
.equ PIN_CLK,        31         @ System clock (1.5 MHz)

@ Convenience masks
.equ MASK_NHALT,     (1 << 27)  @ /HALT pin mask
.equ MASK_RW,        (1 << 26)  @ R/W pin mask
.equ MASK_CLK,       (1 << 31)  @ CLK pin mask

.section .game_rom, "ax"
.align 2

@ --- Game ROM image header (offset 0 of game ROM slot) ---
@ Firmware checks GAME_MAGIC before calling game_main.

.global game_header
.type game_header, %object
game_header:
    .word 0x32795056      @ GAME_MAGIC 'VPy2'
    .word game_main         @ entry point (thumb bit set by linker)
    .word 0x00000000        @ reserved
    .word 0x00000000        @ reserved

@ ================================================================
@ UVM2 Bus Helpers — CLK-synchronized VIA bus mastering
@ Option A: uvm2_via_read  — real CLK-synced read from VIA bus
@ Option B: uvm2_timer_wait — fixed spin-delay (no read needed)
@ bus_read shim selects one; see uvm2/mod.rs emit_uvm2_bus_shims()
@ ================================================================

@ uvm2_bus_init ── configure GPIO directions for UVM2 bus mastering.
@ Must be called once at startup.  Assumes firmware has already muxed
@ GPIO pads to SIO function (standard Pico SDK board setup).
@ No arguments.  Clobbers r0, r1.
.global uvm2_bus_init
.thumb_func
uvm2_bus_init:
    ldr  r0, =0xD0000000    @ SIO_BASE

    @ Pre-drive /HALT and R/W HIGH before enabling outputs.
    @ This avoids a glitch that would spuriously freeze the 6809.
    ldr  r1, =0x0C000000    @ (1<<26) R/W | (1<<27) /HALT
    str  r1, [r0, #0x14]    @ SIO_GPIO_SET

    @ Enable output drivers for address + control lines.
    @ Data bus (GPIO0-7) stays as input until an explicit write.
    ldr  r1, =0x0F3FFF00    @ A0-A13 + A14 + A15 + R/W + /HALT
    str  r1, [r0, #0x24]    @ SIO_GPIO_OE_SET

    bx   lr

@ uvm2_via_write ── write one byte to a Vectrex VIA register.
@
@   r0 = VIA address  (e.g. 0xD001 for PORT_A, 0xD00B for ACR)
@   r1 = data byte
@
@ Clobbers: r2, r3, r4, r5  (r4, r5 preserved via push/pop)
.global uvm2_via_write
.thumb_func
uvm2_via_write:
    push    {r4, r5, lr}

    ldr     r4, =0xD0000000         @ SIO_BASE

    @ ── Step 1: Assert /HALT (take bus from 6809) ──────────────────────
    mov     r5, #(1 << 27)          @ /HALT pin mask
    str     r5, [r4, #0x18]         @ SIO_GPIO_CLR → GPIO27 = 0

    @ ── Step 2: Wait for CLK LOW (GPIO31 = 0) ──────────────────────────
.Luvm2_vw_wait_lo:
    ldr     r2, [r4, #0x04]         @ SIO_GPIO_IN
    tst     r2, #0x80000000         @ bit 31 = CLK
    bne     .Luvm2_vw_wait_lo       @ loop while CLK = 1

    @ ── Step 3: Build GPIO output word ─────────────────────────────────
    @ A0-A13 at GPIO8-21:  (addr << 8) & 0x003FFF00
    lsl     r2, r0, #8
    ldr     r3, =0x003FFF00         @ ADDR_MASK (GPIO8-21 = A0-A13)
    and     r2, r2, r3

    @ A14 = 1 (all VIA addresses have A14=1, VIA lives at $D000-$D00F)
    orr     r2, r2, #(1 << 24)

    @ A15 = 1 (all VIA addresses have A15=1)
    orr     r2, r2, #(1 << 25)

    @ D0-D7 = data byte
    and     r3, r1, #0xFF
    orr     r2, r2, r3              @ R/W (GPIO26) = 0 by absence

    @ Atomically clear all bus lines, then set the new values.
    ldr     r3, =0x073FFFFF         @ D0-D7 | A0-A13 | A14 | A15 | R/W
    str     r3, [r4, #0x18]         @ SIO_GPIO_CLR
    str     r2, [r4, #0x14]         @ SIO_GPIO_SET

    @ Switch D0-D7 to output
    ldr     r3, =0x000000FF
    str     r3, [r4, #0x24]         @ SIO_GPIO_OE_SET

    @ ── Step 4: Wait for CLK HIGH (rising edge → VIA latches write) ────
.Luvm2_vw_wait_hi:
    ldr     r2, [r4, #0x04]         @ SIO_GPIO_IN
    tst     r2, #0x80000000
    beq     .Luvm2_vw_wait_hi       @ loop while CLK = 0

    @ ── Step 5: Release bus ─────────────────────────────────────────────
    @ D0-D7 back to input
    ldr     r3, =0x000000FF
    str     r3, [r4, #0x28]         @ SIO_GPIO_OE_CLR

    @ R/W = 1 (idle)
    mov     r3, #(1 << 26)
    str     r3, [r4, #0x14]         @ SIO_GPIO_SET

    @ /HALT = 1 (release 6809)
    mov     r3, #(1 << 27)
    str     r3, [r4, #0x14]         @ SIO_GPIO_SET

    pop     {r4, r5, pc}

@ ── OPTION A ──────────────────────────────────────────────────────────────
@ uvm2_via_read ── read one byte from a Vectrex VIA register (CLK-synced).
@
@   r0 = VIA address  (e.g. 0xD00D for IFR)
@ Returns:
@   r0 = data byte read from bus
@
@ Clobbers: r2, r3, r4, r5  (r4, r5 preserved via push/pop)
.global uvm2_via_read
.thumb_func
uvm2_via_read:
    push    {r4, r5, lr}

    ldr     r4, =0xD0000000         @ SIO_BASE

    @ Assert /HALT
    mov     r5, #(1 << 27)
    str     r5, [r4, #0x18]         @ SIO_GPIO_CLR → GPIO27 = 0

    @ Wait for CLK LOW
.Luvm2_vr_wait_lo:
    ldr     r2, [r4, #0x04]
    tst     r2, #0x80000000
    bne     .Luvm2_vr_wait_lo

    @ Build address word: (addr << 8) & ADDR_MASK, A14+A15=1
    lsl     r2, r0, #8
    ldr     r3, =0x003FFF00
    and     r2, r2, r3
    orr     r2, r2, #(1 << 24)      @ A14 = 1
    orr     r2, r2, #(1 << 25)      @ A15 = 1

    @ Clear all bus lines, then set address
    ldr     r3, =0x073FFFFF
    str     r3, [r4, #0x18]         @ SIO_GPIO_CLR
    str     r2, [r4, #0x14]         @ SIO_GPIO_SET (no D0-D7, R/W implicit HIGH)

    @ R/W = 1 (read) — ensure high
    mov     r3, #(1 << 26)
    str     r3, [r4, #0x14]

    @ D0-D7 as input (already input from init, ensure OE off)
    ldr     r3, =0x000000FF
    str     r3, [r4, #0x28]         @ SIO_GPIO_OE_CLR

    @ Wait for CLK HIGH — VIA drives D0-D7 on this edge
.Luvm2_vr_wait_hi:
    ldr     r2, [r4, #0x04]
    tst     r2, #0x80000000
    beq     .Luvm2_vr_wait_hi

    @ Sample D0-D7 (GPIO bits 0-7)
    ldr     r0, [r4, #0x04]         @ SIO_GPIO_IN
    and     r0, r0, #0xFF

    @ Release bus
    ldr     r3, =0x073FFF00         @ clear address lines
    str     r3, [r4, #0x18]
    mov     r3, #(1 << 27)          @ /HALT = 1
    str     r3, [r4, #0x14]

    pop     {r4, r5, pc}

@ ── OPTION B ──────────────────────────────────────────────────────────────
@ uvm2_timer_wait ── spin-delay equivalent to VIA T1 at $7F/$00 (86 µs).
@ Returns r0 = 0x40 (mimics IFR bit6 set = timer done).
@ No bus access needed — the VIA timer is still ticking independently.
@ At 150 MHz RP2350, 86 µs = 12,900 cycles; +20% margin = 15,500 cycles.
.global uvm2_timer_wait
.thumb_func
uvm2_timer_wait:
    ldr     r0, =7750               @ loop count (2 cycles/iteration × 7750 = 15500)
.Luvm2_tw_loop:
    subs    r0, r0, #1
    bne     .Luvm2_tw_loop
    mov     r0, #0x40               @ return IFR=done to satisfy tst r0,#0x40
    bx      lr

@ --- UVM2 bus shims: bus_write / bus_read → CLK-synced GPIO ---
@ bus_write(r0=addr, r1=data) — delegates to uvm2_via_write
.global bus_write
.thumb_func
bus_write:
    b       uvm2_via_write

@ bus_read(r0=addr) → r0=data
@ OPTION A: real CLK-synced read  → uncomment the line below
@ OPTION B: fixed spin-delay      → uncomment the line below
@ Change one line to switch between them. Default: OPTION B (safer first test).
.global bus_read
.thumb_func
bus_read:
    @ OPTION A (CLK-synced read):
    @ b       uvm2_via_read
    @ OPTION B (spin delay, always returns 0x40 = timer done):
    b       uvm2_timer_wait

@ ============================================================
@ Drawing engine — ARM Thumb2 / RP2350 bus master
@ ============================================================

@ SIN_TABLE[128]: sin(i*2π/128)*127 as i8
.global _SIN_TABLE
_SIN_TABLE:
    .byte   0x00, 0x06, 0x0C, 0x13, 0x19, 0x1F, 0x25, 0x2B, 0x31, 0x36, 0x3C, 0x41, 0x47, 0x4C, 0x51, 0x55
    .byte   0x5A, 0x5E, 0x62, 0x66, 0x6A, 0x6D, 0x70, 0x73, 0x75, 0x78, 0x7A, 0x7B, 0x7D, 0x7E, 0x7E, 0x7F
    .byte   0x7F, 0x7F, 0x7E, 0x7E, 0x7D, 0x7B, 0x7A, 0x78, 0x75, 0x73, 0x70, 0x6D, 0x6A, 0x66, 0x62, 0x5E
    .byte   0x5A, 0x55, 0x51, 0x4C, 0x47, 0x41, 0x3C, 0x36, 0x31, 0x2B, 0x25, 0x1F, 0x19, 0x13, 0x0C, 0x06
    .byte   0x00, 0xFA, 0xF4, 0xED, 0xE7, 0xE1, 0xDB, 0xD5, 0xCF, 0xCA, 0xC4, 0xBF, 0xB9, 0xB4, 0xAF, 0xAB
    .byte   0xA6, 0xA2, 0x9E, 0x9A, 0x96, 0x93, 0x90, 0x8D, 0x8B, 0x88, 0x86, 0x85, 0x83, 0x82, 0x82, 0x81
    .byte   0x81, 0x81, 0x82, 0x82, 0x83, 0x85, 0x86, 0x88, 0x8B, 0x8D, 0x90, 0x93, 0x96, 0x9A, 0x9E, 0xA2
    .byte   0xA6, 0xAB, 0xAF, 0xB4, 0xB9, 0xBF, 0xC4, 0xCA, 0xCF, 0xD5, 0xDB, 0xE1, 0xE7, 0xED, 0xF4, 0xFA

@ smul_lut(r0=val i8, r1=angle 0-127) → r0=(val*sin)>>7
.global smul_lut
.type smul_lut, %function
.thumb_func
smul_lut:
    ldr     r2, =_SIN_TABLE
    and     r1, r1, #0x7F
    ldrb    r2, [r2, r1]
    sxtb    r2, r2
    sxtb    r0, r0
    mul     r0, r0, r2
    asr     r0, r0, #7
    bx      lr

@ dv_reset() — reset Vectrex integrators, set ACR=$18
.global dv_reset
.type dv_reset, %function
.thumb_func
dv_reset:
    push    {lr}
    mov     r0, #0xD00A
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD00B
    mov     r1, #0x18
    bl      bus_write
    mov     r0, #0xD00C
    mov     r1, #0xCC
    bl      bus_write
    mov     r0, #0xD001
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x03
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x02
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x02
    bl      bus_write
    pop     {pc}
    .ltorg

@ dv_move_to(r0=dx, r1=dy) — position beam, no draw
.global dv_move_to
.type dv_move_to, %function
.thumb_func
dv_move_to:
    push    {r4, r5, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r0, #0xD001
    mov     r1, r5
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #60
dv_mt_s: subs r0,r0,#1
    bne dv_mt_s
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD001
    mov     r1, r4
    bl      bus_write
    mov     r0, #0xD00A
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD006
    mov     r1, #0x7F
    bl      bus_write
    mov     r0, #0xD005
    mov     r1, #0x00
    bl      bus_write
dv_mt_p: mov r0,#0xD00D
    bl bus_read
    tst r0,#0x40
    beq dv_mt_p
    mov     r0, #0xD004
    bl      bus_read
    pop     {r4, r5, pc}
    .ltorg

@ dv_draw_delta(r0=dx, r1=dy) — draw one vector segment
.global dv_draw_delta
.type dv_draw_delta, %function
.thumb_func
dv_draw_delta:
    push    {r4, r5, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r0, #0xD001
    mov     r1, r5
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #60
dv_dd_s: subs r0,r0,#1
    bne dv_dd_s
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD001
    mov     r1, r4
    bl      bus_write
    mov     r0, #0xD00A
    mov     r1, #0xFF
    bl      bus_write
    mov     r0, #0xD006
    mov     r1, #0x7F
    bl      bus_write
    mov     r0, #0xD005
    mov     r1, #0x00
    bl      bus_write
dv_dd_p: mov r0,#0xD00D
    bl bus_read
    tst r0,#0x40
    beq dv_dd_p
    mov     r0, #0xD00A
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD004
    bl      bus_read
    pop     {r4, r5, pc}
    .ltorg

@ vpy_draw_vector(r0=asset_ptr, r1=ox, r2=oy)
@ Draws asset at screen position (ox, oy). ox=0, oy=0 = screen centre.
.global vpy_draw_vector
.type vpy_draw_vector, %function
.thumb_func
vpy_draw_vector:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    mov     r4, r0              @ asset_ptr
    mov     r9, r1              @ ox
    mov     r10, r2             @ oy
    ldr     r5, [r4]            @ path_count
    mov     r6, #0              @ path index
dvv_pl:
    cmp     r6, r5
    bge     dvv_done
    lsl     r7, r6, #2
    add     r7, r7, #4
    ldr     r7, [r4, r7]
    bl      dv_reset
    ldrb    r0, [r7]
    bl      vpy_set_intensity
    ldrsb   r0, [r7, #2]
    add     r0, r0, r9
    ldrsb   r1, [r7, #1]
    add     r1, r1, r10
    bl      dv_move_to
    add     r8, r7, #5
dvv_cl:
    ldrb    r0, [r8]
    cmp     r0, #0x02
    beq     dvv_cend
    cmp     r0, #0xFF
    bne     dvv_cskip
    ldrsb   r0, [r8, #2]
    ldrsb   r1, [r8, #1]
    bl      dv_draw_delta
    add     r8, r8, #3
    b       dvv_cl
dvv_cskip:
    add     r8, r8, #1
    b       dvv_cl
dvv_cend:
    add     r6, r6, #1
    b       dvv_pl
dvv_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ vpy_draw_vector_3d(r0,r1=ax,r2=ay,r3=az,[sp+36]=ox,[sp+40]=oy)
.global vpy_draw_vector_3d
.type vpy_draw_vector_3d, %function
.thumb_func
vpy_draw_vector_3d:
    push    {r4,r5,r6,r7,r8,r9,r10,r11,lr}
    mov     r4, r0
    mov     r5, r1               @ ax
    mov     r6, r2               @ ay
    mov     r7, r3               @ az
    ldrsb   r8, [sp, #36]        @ ox (sign-extend)
    ldrsb   r9, [sp, #40]        @ oy
    ldr     r0, =_dv3d_cos
    add     r1, r5, #32
    and r1,r1,#0x7F
    strb r1,[r0]
    add     r1, r6, #32
    and r1,r1,#0x7F
    strb r1,[r0,#1]
    add     r1, r7, #32
    and r1,r1,#0x7F
    strb r1,[r0,#2]
    ldr     r10, [r4]
    add r4,r4,#4
    ldr     r11, =_dv3d_vbuf
dv3_vl:
    cmp r10,#0
    beq dv3_vd
    sub r10,r10,#1
    ldr     r0, =_dv3d_tmp
    ldrsb   r1, [r4]
    strb r1,[r0]
    ldrsb   r1, [r4,#1]
  strb r1,[r0,#1]
    ldrsb   r1, [r4,#2]
  strb r1,[r0,#2]
    add     r4, r4, #3
    ldr     r0,=_dv3d_tmp
    ldrsb   r0,[r0,#1]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#0]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    strb r0,[r2]
    ldr     r0,=_dv3d_tmp
    ldrsb   r0,[r0,#2]
    mov     r1,r5
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    ldrsb r3,[r2]
    sub r0,r3,r0
    strb r0,[r2,#1]
    ldr     r0,=_dv3d_tmp
    ldrsb   r0,[r0,#1]
    mov     r1,r5
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    strb r0,[r2]
    ldr     r0,=_dv3d_tmp
    ldrsb   r0,[r0,#2]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#0]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    ldrsb r3,[r2]
    add r0,r0,r3
    strb r0,[r2,#2]
    ldr     r0,=_dv3d_tmp
    ldrsb   r0,[r0,#0]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#1]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    strb r0,[r2]
    ldr     r0,=_dv3d_sm
    ldrsb   r0,[r0,#2]
    mov     r1,r6
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    ldrsb r3,[r2]
    add r0,r0,r3
    strb r0,[r2,#3]
    ldr     r0,=_dv3d_sm
    ldrsb   r0,[r0,#3]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#2]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    strb r0,[r2]
    ldr     r0,=_dv3d_sm
    ldrsb   r0,[r0,#1]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#2]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    ldrsb r3,[r2]
    sub r0,r3,r0
    add r0,r0,r8
    strb    r0,[r11]
    ldr     r0,=_dv3d_sm
    ldrsb   r0,[r0,#3]
    mov     r1,r7
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    strb r0,[r2]
    ldr     r0,=_dv3d_sm
    ldrsb   r0,[r0,#1]
    ldr     r2,=_dv3d_cos
    ldrb    r1,[r2,#2]
    bl      smul_lut
    ldr     r2,=_dv3d_sm
    ldrsb r3,[r2]
    add r0,r0,r3
    add r0,r0,r9
    strb    r0,[r11,#1]
    add     r11,r11,#2
    b dv3_vl
dv3_vd:
    bl      dv_reset
    ldr     r10,[r4]
    add r4,r4,#4
    ldr     r11,=_dv3d_vbuf
    ldr     r0,=_dv3d_cur
    mov r1,#0
    strh r1,[r0]
dv3_pl:
    cmp r10,#0
    beq dv3_pd
    sub r10,r10,#1
    ldrb    r5,[r4]              @ pt_count
    ldrb    r6,[r4,#1]           @ closed
    add     r4,r4,#2
    cmp     r5,#0
    beq dv3_pnext_emp
    mov     r7, r4
    ldrb    r0,[r7]
    lsl r2,r0,#1
    ldrsb   r0,[r11,r2]
    add     r2,r2,#1
    ldrsb r1,[r11,r2]
    ldr     r2,=_dv3d_cur
    ldrsb   r3,[r2,#0]
    sub r0,r0,r3
    ldrsb   r3,[r2,#1]
    sub r1,r1,r3
    push    {r0,r1}
    ldrb    r0,[r7]
    lsl r2,r0,#1
    ldrsb   r8,[r11,r2]
    add     r2,r2,#1
    ldrsb r9,[r11,r2]
    ldr     r2,=_dv3d_cur
    strb r8,[r2]
    strb r9,[r2,#1]
    pop     {r0,r1}
    bl      dv_move_to
    sub     r5,r5,#1
    add r7,r7,#1
dv3_vxtx:
    cmp     r5,#0
    beq dv3_close
    sub r5,r5,#1
    ldrb    r0,[r7]
    lsl r2,r0,#1
    ldrsb   r0,[r11,r2]
    add     r2,r2,#1
    ldrsb r1,[r11,r2]
    push    {r0,r1}
    ldr     r2,=_dv3d_cur
    ldrsb   r3,[r2,#0]
    sub r0,r0,r3
    ldrsb   r3,[r2,#1]
    sub r1,r1,r3
    bl      dv_draw_delta
    pop     {r0,r1}
    ldr     r2,=_dv3d_cur
    strb r0,[r2]
    strb r1,[r2,#1]
    add     r7,r7,#1
    b dv3_vxtx
dv3_close:
    cmp     r6,#0
    beq dv3_pnext
    ldr     r2,=_dv3d_cur
    ldrsb   r3,[r2,#0]
    sub r0,r8,r3
    ldrsb   r3,[r2,#1]
    sub r1,r9,r3
    bl      dv_draw_delta
    ldr     r2,=_dv3d_cur
    strb r8,[r2]
    strb r9,[r2,#1]
dv3_pnext:
    mov     r4,r7
    b dv3_pl
dv3_pnext_emp:
    b       dv3_pl
dv3_pd:
    pop     {r4,r5,r6,r7,r8,r9,r10,r11,pc}
    .ltorg

