@ vpy_wait_recal() — wait for VIA Timer 1 (frame sync)
.global vpy_wait_recal
.type vpy_wait_recal, %function
.thumb_func
vpy_wait_recal:
    push    {lr}
    mov     r0, #0xD006
    mov     r1, #0x7F
    bl      bus_write
    mov     r0, #0xD007
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD005
    mov     r1, #0x00
    bl      bus_write
vpy_wr_poll:
    mov     r0, #0xD00D
    bl      bus_read
    tst     r0, #0x40
    beq     vpy_wr_poll
    mov     r0, #0xD004
    bl      bus_read
    pop     {pc}
    .ltorg

@ vpy_set_intensity(r0=intensity 0-127)
.global vpy_set_intensity
.type vpy_set_intensity, %function
.thumb_func
vpy_set_intensity:
    push    {lr}
    and     r1, r0, #0x7F
    mov     r0, #0xD001
    bl      bus_write
    pop     {pc}
    .ltorg

@ vpy_move(r0=x, r1=y) — position beam (absolute from current)
.global vpy_move
.type vpy_move, %function
.thumb_func
vpy_move:
    push    {r4, r5, lr}
    mov     r4, r0
    mov     r5, r1
    ldr     r0, =VPY_MOVE_X
    str     r4, [r0]            @ VPY_MOVE_X = x
    str     r5, [r0, #4]        @ VPY_MOVE_Y = y  (VPY_MOVE_Y = VPY_MOVE_X + 4)
    mov     r0, #0xD001
    mov     r1, r5
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD001
    mov     r1, r4
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    pop     {r4, r5, pc}
    .ltorg

@ vpy_draw_line(r0=x0, r1=y0, r2=x1, r3=y1, [sp+0]=intensity)
@ Splits segments longer than 127 units using SDIV for proportional steps
.global vpy_draw_line
.type vpy_draw_line, %function
.thumb_func
vpy_draw_line:
    push    {r4, r5, r6, r7, r8, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r7, r3
    ldr     r2, =VPY_MOVE_X
    ldr     r3, [r2]            @ r3 = VPY_MOVE_X
    ldr     r2, [r2, #4]        @ r2 = VPY_MOVE_Y
    add     r4, r4, r3          @ x0 += MOVE_X
    add     r5, r5, r2          @ y0 += MOVE_Y
    add     r6, r6, r3          @ x1 += MOVE_X
    add     r7, r7, r2          @ y1 += MOVE_Y
    ldr     r8, [sp, #24]           @ intensity (5th arg, past 6 saved regs)
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    sub     r4, r6, r4
    sub     r5, r7, r5
    movs    r6, r4
    bpl     vdl_dx_pos
    neg     r6, r4
vdl_dx_pos:
    movs    r7, r5
    bpl     vdl_dy_pos
    neg     r7, r5
vdl_dy_pos:
    cmp     r6, r7
    it      ge
    movge   r7, r6
    cmp     r7, #0
    beq     vdl_done
    add     r7, r7, #126
    mov     r6, #127
    sdiv    r8, r7, r6
vdl_loop:
    cmp     r8, #0
    beq     vdl_done
    sdiv    r0, r4, r8
    sdiv    r1, r5, r8
    sub     r4, r4, r0
    sub     r5, r5, r1
    sub     r8, r8, #1
    bl      dv_draw_delta
    b       vdl_loop
vdl_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vpy_draw_vector_ex(r0=asset, r1=ox, r2=oy, r3=mirror, [sp+0]=intensity)
@ Draws asset centered at (ox,oy); mirror: bit0=flipX, bit1=flipY
@ dv_reset called before EVERY path so each path starts from screen centre.
.global vpy_draw_vector_ex
.type vpy_draw_vector_ex, %function
.thumb_func
vpy_draw_vector_ex:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    mov     r4, r0              @ asset_ptr
    mov     r9, r1              @ ox  (kept for whole function)
    mov     r10, r2             @ oy  (kept for whole function)
    mov     r7, r3              @ mirror
    ldr     r8, [sp, #32]       @ intensity arg (8 saved regs = 32 bytes)
    ldr     r5, [r4]            @ path_count
    mov     r6, #0              @ path_idx
dvex_pl:
    cmp     r6, r5
    bge     dvex_done
    lsl     r3, r6, #2
    add     r3, r3, #4
    ldr     r3, [r4, r3]
    bl      dv_reset
    ldrb    r0, [r3]            @ .vec per-path intensity
    cmp     r8, #0
    it      ne
    movne   r0, r8             @ if intensity arg != 0, use it
    bl      vpy_set_intensity
    ldrsb   r0, [r3, #2]        @ x_start
    ldrsb   r1, [r3, #1]        @ y_start
    tst     r7, #1
    beq     dvex_nfx
    neg     r0, r0
dvex_nfx:
    tst     r7, #2
    beq     dvex_nfy
    neg     r1, r1
dvex_nfy:
    add     r0, r0, r9          @ x_start + ox
    add     r1, r1, r10         @ y_start + oy
    bl      dv_move_to
    add     r2, r3, #5          @ command ptr
dvex_cl:
    ldrb    r0, [r2]
    cmp     r0, #0x02
    beq     dvex_cend
    cmp     r0, #0xFF
    bne     dvex_cskip
    ldrsb   r0, [r2, #2]        @ dx
    ldrsb   r1, [r2, #1]        @ dy
    tst     r7, #1
    beq     dvex_nfx2
    neg     r0, r0
dvex_nfx2:
    tst     r7, #2
    beq     dvex_nfy2
    neg     r1, r1
dvex_nfy2:
    bl      dv_draw_delta
    add     r2, r2, #3
    b       dvex_cl
dvex_cskip:
    add     r2, r2, #1
    b       dvex_cl
dvex_cend:
    add     r6, r6, #1
    b       dvex_pl
dvex_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ vpy_draw_circle(r0=cx, r1=cy, r2=radius, r3=intensity)
@ 16-segment circle via sin/cos LUT
.global vpy_draw_circle
.type vpy_draw_circle, %function
.thumb_func
vpy_draw_circle:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    sub     sp, sp, #8              @ [sp+0]=first_x [sp+4]=first_y
    mov     r4, r0                  @ cx
    mov     r5, r1                  @ cy
    asr     r6, r2, #1              @ r6 = diam/2 = radius (matches M6809 convention)
    mov     r7, r3                  @ intensity
    bl      dv_reset
    mov     r0, r7
    bl      vpy_set_intensity
    mov     r0, #0
    bl      vpy_cos
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r9, r4, r0              @ prev_x = cx + cos(0)*r/127
    mov     r0, #0
    bl      vpy_sin
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r10, r5, r0             @ prev_y = cy + sin(0)*r/127
    str     r9, [sp]
    str     r10, [sp, #4] @ save first point
    mov     r0, r9
    mov     r1, r10
    bl      dv_move_to
    mov     r8, #1
vpy_dc_loop:
    cmp     r8, #16
    bge     vpy_dc_close
    lsl     r0, r8, #3
    bl      vpy_cos
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r11, r4, r0             @ new_x
    lsl     r0, r8, #3
    bl      vpy_sin
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r0, r5, r0              @ new_y in r0
    sub     r2, r11, r9             @ dx = new_x - prev_x
    sub     r3, r0, r10             @ dy = new_y - prev_y
    mov     r9, r11                 @ prev_x = new_x
    mov     r10, r0                 @ prev_y = new_y
    mov     r0, r2
    mov     r1, r3
    bl      dv_draw_delta
    add     r8, r8, #1
    b       vpy_dc_loop
vpy_dc_close:
    ldr     r0, [sp]                @ first_x
    ldr     r1, [sp, #4]            @ first_y
    sub     r0, r0, r9              @ dx = first_x - prev_x
    sub     r1, r1, r10             @ dy = first_y - prev_y
    bl      dv_draw_delta
    add     sp, sp, #8
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_draw_rect(r0=x, r1=y, r2=w, r3=h, [sp+0]=intensity)
.global vpy_draw_rect
.type vpy_draw_rect, %function
.thumb_func
vpy_draw_rect:
    push    {r4, r5, r6, r7, r8, lr}    @ 24 bytes
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r7, r3
    ldr     r8, [sp, #24]               @ intensity
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    mov     r0, r6
    mov     r1, #0
    bl      dv_draw_delta
    mov     r0, #0
    mov     r1, r7
    bl      dv_draw_delta
    neg     r0, r6
    mov     r1, #0
    bl      dv_draw_delta
    mov     r0, #0
    neg     r1, r7
    bl      dv_draw_delta
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vpy_draw_filled_rect(r0=x, r1=y, r2=w, r3=h, [sp+28]=intensity)
@ Outer outline (vpy_draw_rect) + horizontal scan lines (step=3)
.global vpy_draw_filled_rect
.type vpy_draw_filled_rect, %function
.thumb_func
vpy_draw_filled_rect:
    push    {r4, r5, r6, r7, r8, r9, lr}    @ 28 bytes
    mov     r4, r0              @ x
    mov     r5, r1              @ y
    mov     r6, r2              @ w
    mov     r7, r3              @ h
    ldr     r8, [sp, #28]       @ intensity
    push    {r8}                @ intensity as 5th arg
    mov     r0, r4
    mov     r1, r5
    mov     r2, r6
    mov     r3, r7
    bl      vpy_draw_rect
    add     sp, sp, #4
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    mov     r9, #0              @ scan offset
vdfr_loop:
    cmp     r9, r7
    bge     vdfr_done
    mov     r0, r6
    mov     r1, #0
    bl      dv_draw_delta
    add     r9, r9, #3
    cmp     r9, r7
    bge     vdfr_done
    neg     r0, r6
    mov     r1, #3
    bl      dv_move_to
    b       vdfr_loop
vdfr_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ vpy_draw_polygon(r0=n, r1=intensity, r2=x0, r3=y0, [sp+0]=x1,y1,...)
.global vpy_draw_polygon
.type vpy_draw_polygon, %function
.thumb_func
vpy_draw_polygon:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}  @ 36 bytes
    mov     r4, r0              @ n (total vertices)
    mov     r5, r1              @ intensity
    mov     r6, r2              @ first_x
    mov     r7, r3              @ first_y
    add     r8, sp, #36         @ ptr to x1 (first extra stack arg)
    mov     r9, r6              @ prev_x = first_x
    mov     r10, r7             @ prev_y = first_y
    bl      dv_reset
    mov     r0, r5
    bl      vpy_set_intensity
    mov     r0, r6
    mov     r1, r7
    bl      dv_move_to
    mov     r11, #1             @ vertex idx = 1
vdpoly_loop:
    cmp     r11, r4
    bge     vdpoly_close
    ldr     r0, [r8]            @ xi
    ldr     r1, [r8, #4]        @ yi
    add     r8, r8, #8
    sub     r2, r0, r9          @ dx = xi - prev_x
    sub     r3, r1, r10         @ dy = yi - prev_y
    mov     r9, r0
    mov     r10, r1
    mov     r0, r2
    mov     r1, r3
    bl      dv_draw_delta
    add     r11, r11, #1
    b       vdpoly_loop
vdpoly_close:
    sub     r0, r6, r9          @ dx = first_x - prev_x
    sub     r1, r7, r10         @ dy = first_y - prev_y
    bl      dv_draw_delta
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_draw_ellipse(r0=cx, r1=cy, r2=rx, r3=ry, [sp+0]=intensity)
@ 16-segment parametric ellipse via sin/cos LUT
.global vpy_draw_ellipse
.type vpy_draw_ellipse, %function
.thumb_func
vpy_draw_ellipse:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}  @ 36 bytes
    sub     sp, sp, #8          @ [sp+0]=first_x [sp+4]=first_y
    mov     r4, r0              @ cx
    mov     r5, r1              @ cy
    mov     r6, r2              @ rx
    mov     r7, r3              @ ry
    ldr     r8, [sp, #44]       @ intensity (8+36=44)
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, #0
    bl      vpy_cos
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r8, r4, r0          @ prev_x = cx + rx*cos(0)/127
    str     r8, [sp, #0]        @ first_x
    mov     r0, #0
    bl      vpy_sin
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r9, r5, r0          @ prev_y = cy + ry*sin(0)/127
    str     r9, [sp, #4]        @ first_y
    mov     r0, r8
    mov     r1, r9
    bl      dv_move_to
    mov     r10, #1             @ i = 1
vde_loop:
    cmp     r10, #16
    bge     vde_close
    lsl     r0, r10, #3         @ angle = i*8
    bl      vpy_cos
    mul     r0, r0, r6
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r11, r4, r0         @ new_x = cx + rx*cos/127
    lsl     r0, r10, #3
    bl      vpy_sin
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r0, r5, r0          @ new_y
    sub     r2, r11, r8         @ dx = new_x - prev_x
    sub     r3, r0, r9          @ dy = new_y - prev_y
    mov     r8, r11             @ prev_x = new_x
    mov     r9, r0              @ prev_y = new_y
    mov     r0, r2
    mov     r1, r3
    bl      dv_draw_delta
    add     r10, r10, #1
    b       vde_loop
vde_close:
    ldr     r0, [sp, #0]        @ first_x
    ldr     r1, [sp, #4]        @ first_y
    sub     r0, r0, r8          @ dx = first_x - prev_x
    sub     r1, r1, r9          @ dy = first_y - prev_y
    bl      dv_draw_delta
    add     sp, sp, #8
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_draw_arc(r0=segs, r1=cx, r2=cy, r3=r, [sp+0]=start_deg, [sp+4]=sweep_deg, [sp+8]=intensity)
.global vpy_draw_arc
.type vpy_draw_arc, %function
.thumb_func
vpy_draw_arc:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}  @ 36 bytes
    mov     r4, r0              @ segs (loop counter)
    mov     r5, r1              @ cx
    mov     r6, r2              @ cy
    mov     r7, r3              @ radius
    ldr     r0, [sp, #36]       @ start_deg
    lsl     r0, r0, #7          @ * 128
    mov     r1, #360
    sdiv    r8, r0, r1          @ r8 = start_step
    ldr     r0, [sp, #40]       @ sweep_deg
    lsl     r0, r0, #7
    sdiv    r0, r0, r1          @ sweep_steps (r1 still 360)
    cmp     r4, #0
    beq     vpy_arc_done
    sdiv    r9, r0, r4          @ r9 = step_size = sweep_steps / segs
    ldr     r0, [sp, #44]       @ intensity
    bl      dv_reset
    bl      vpy_set_intensity
    and     r0, r8, #127
    bl      vpy_cos
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r10, r5, r0         @ prev_x = cx + r*cos(start)/127
    and     r0, r8, #127
    bl      vpy_sin
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r11, r6, r0         @ prev_y = cy + r*sin(start)/127
    mov     r0, r10
    mov     r1, r11
    bl      dv_move_to
vpy_arc_loop:
    cmp     r4, #0
    beq     vpy_arc_done
    add     r8, r8, r9          @ current_angle += step_size
    and     r0, r8, #127
    bl      vpy_cos
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r0, r5, r0          @ new_x
    push    {r0}                @ save new_x (r0 clobbered by next bl)
    and     r0, r8, #127
    bl      vpy_sin
    mul     r0, r0, r7
    mov     r1, #127
    sdiv    r0, r0, r1
    add     r1, r6, r0          @ new_y
    pop     {r0}                @ restore new_x
    sub     r2, r0, r10         @ dx = new_x - prev_x
    sub     r3, r1, r11         @ dy = new_y - prev_y
    mov     r10, r0             @ prev_x = new_x
    mov     r11, r1             @ prev_y = new_y
    mov     r0, r2
    mov     r1, r3
    bl      dv_draw_delta
    sub     r4, r4, #1
    b       vpy_arc_loop
vpy_arc_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_draw_bezier(x0,y0,cp1x,cp1y,[sp+0]=cp2x,cp2y,x1,y1,steps,intensity)
.global vpy_draw_bezier
.type vpy_draw_bezier, %function
.thumb_func
vpy_draw_bezier:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    sub     sp, sp, #36
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r7, r3
    ldr     r8,  [sp, #72]      @ cp2x
    ldr     r9,  [sp, #76]      @ cp2y
    ldr     r10, [sp, #80]      @ x1
    ldr     r11, [sp, #84]      @ y1
    ldr     r1,  [sp, #88]      @ steps
    ldr     r0,  [sp, #92]      @ intensity
    cmp     r1, #1
    blt     vbez_done
    str     r1, [sp]
    mov     r1, #1
    str     r1, [sp, #4]
    bl      dv_reset
    bl      vpy_set_intensity
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    str     r4, [sp, #8]
    str     r5, [sp, #12]
vbez_loop:
    ldr     r0, [sp, #4]
    ldr     r1, [sp]
    cmp     r0, r1
    bgt     vbez_done
    lsl     r2, r0, #8
    sdiv    r2, r2, r1
    sub     r0, r6, r4
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r4
    str     r0, [sp, #20]
    sub     r0, r7, r5
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r5
    str     r0, [sp, #24]
    sub     r0, r8, r6
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r6
    str     r0, [sp, #28]
    sub     r0, r9, r7
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r7
    str     r0, [sp, #32]
    sub     r1, r10, r8
    mul     r1, r1, r2
    asr     r1, r1, #8
    add     r1, r1, r8
    sub     r3, r11, r9
    mul     r3, r3, r2
    asr     r3, r3, #8
    add     r3, r3, r9
    ldr     r12, [sp, #20]
    ldr     r0, [sp, #28]
    sub     r0, r0, r12
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r12
    str     r0, [sp, #20]
    ldr     r12, [sp, #24]
    ldr     r0, [sp, #32]
    sub     r0, r0, r12
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r12
    str     r0, [sp, #24]
    ldr     r12, [sp, #28]
    sub     r1, r1, r12
    mul     r1, r1, r2
    asr     r1, r1, #8
    add     r1, r1, r12
    str     r1, [sp, #28]
    ldr     r12, [sp, #32]
    sub     r3, r3, r12
    mul     r3, r3, r2
    asr     r3, r3, #8
    add     r3, r3, r12
    str     r3, [sp, #32]
    ldr     r12, [sp, #20]
    ldr     r0, [sp, #28]
    sub     r0, r0, r12
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r12
    ldr     r12, [sp, #24]
    ldr     r1, [sp, #32]
    sub     r1, r1, r12
    mul     r1, r1, r2
    asr     r1, r1, #8
    add     r1, r1, r12
    ldr     r2, [sp, #8]        @ prev_x
    ldr     r3, [sp, #12]       @ prev_y
    str     r0, [sp, #8]        @ prev_x = bx
    str     r1, [sp, #12]       @ prev_y = by
    sub     r0, r0, r2          @ dx = bx - prev_x
    sub     r1, r1, r3          @ dy = by - prev_y
    bl      dv_draw_delta
    ldr     r0, [sp, #4]
    add     r0, r0, #1
    str     r0, [sp, #4]
    b       vbez_loop
vbez_done:
    add     sp, sp, #36
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_draw_bezier_quad(x0,y0,cpx,cpy,[sp+0]=x1,y1,steps,intensity)
.global vpy_draw_bezier_quad
.type vpy_draw_bezier_quad, %function
