    sub     r3, r6, r4
    mul     r3, r3, r2
    asr     r3, r3, #8
    add     r3, r3, r4
    sub     r0, r8, r6
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r6
    sub     r0, r0, r3
    mul     r0, r0, r2
    asr     r0, r0, #8
    add     r0, r0, r3
    str     r0, [sp, #20]
    sub     r3, r7, r5
    mul     r3, r3, r2
    asr     r3, r3, #8
    add     r3, r3, r5
    sub     r1, r9, r7
    mul     r1, r1, r2
    asr     r1, r1, #8
    add     r1, r1, r7
    sub     r1, r1, r3
    mul     r1, r1, r2
    asr     r1, r1, #8
    add     r1, r1, r3
    ldr     r0, [sp, #20]       @ bx
    ldr     r2, [sp, #8]        @ prev_x
    ldr     r3, [sp, #12]       @ prev_y
    str     r0, [sp, #8]        @ prev_x = bx
    str     r1, [sp, #12]       @ prev_y = by
    sub     r0, r0, r2          @ dx
    sub     r1, r1, r3          @ dy
    bl      dv_draw_delta
    ldr     r0, [sp, #4]
    add     r0, r0, #1
    str     r0, [sp, #4]
    b       vbezq_loop
vbezq_done:
    add     sp, sp, #28
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ vpy_print_text(r0=x, r1=y, r2=str_ptr)
.global vpy_print_text
.type vpy_print_text, %function
.thumb_func
vpy_print_text:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    ldr     r7, =TEXT_SIZE
    ldr     r7, [r7]
    cmp     r7, #0
    bne     vpt_sc
    mov     r7, #3
vpt_sc:
    ldr     r8, =TEXT_COLOR
    ldr     r8, [r8]
    cmp     r8, #0
    bne     vpt_cc
    mov     r8, #100
vpt_cc:
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, #6
    mul     r0, r0, r7
    asr     r0, r0, #1
    sub     r5, r5, r0
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    ldr     r10, =PRINT_BEAM_X
    str     r4, [r10]
    ldr     r11, =PRINT_BEAM_Y
    str     r5, [r11]
    mov     r9, r4              @ cur_x = x
vpt_loop:
    ldrb    r0, [r6]
    add     r6, r6, #1
    cmp     r0, #0
    beq     vpt_done
    cmp     r0, #0x80
    beq     vpt_done
    cmp     r0, #0x61
    blt     vpt_nl
    cmp     r0, #0x7A
    bgt     vpt_nl
    sub     r0, r0, #0x20
vpt_nl:
    cmp     r0, #32
    blt     vpt_adv
    cmp     r0, #126
    bgt     vpt_adv
    sub     r0, r0, #32
    ldr     r1, =_FONT_PTRS
    lsl     r0, r0, #2
    ldr     r0, [r1, r0]
    cmp     r0, #0
    beq     vpt_adv
    mov     r1, r9
    mov     r2, r5
    mov     r3, r7
    push    {r10, r11}
    bl      vpt_draw_glyph
    add     sp, sp, #8
vpt_adv:
    mov     r0, #7
    mul     r0, r0, r7
    asr     r0, r0, #1
    add     r9, r9, r0
    b       vpt_loop
vpt_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpt_draw_glyph — internal: draw one glyph at (char_x, char_y) with scale
.type vpt_draw_glyph, %function
.thumb_func
vpt_draw_glyph:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0              @ glyph_ptr
    mov     r5, r1              @ char_x
    mov     r6, r2              @ char_y
    mov     r7, r3              @ scale
    ldr     r8, [sp, #36]       @ bx_ptr (PRINT_BEAM_X)
    ldr     r9, [sp, #40]       @ by_ptr (PRINT_BEAM_Y)
    ldr     r10, [r8]           @ beam_x
    ldr     r11, [r9]           @ beam_y
vdg_loop:
    ldrb    r0, [r4]
    cmp     r0, #0
    beq     vdg_done
    ldrb    r1, [r4, #1]        @ gx
    ldrb    r2, [r4, #2]        @ gy
    add     r4, r4, #3
    push    {r0}               @ save cmd
    mul     r1, r1, r7
    asr     r1, r1, #1
    add     r1, r1, r5
    mul     r2, r2, r7
    asr     r2, r2, #1
    add     r2, r2, r6
    sub     r0, r1, r10         @ dx
    sub     r3, r2, r11         @ dy
    mov     r10, r1
    mov     r11, r2
    pop     {r1}               @ restore cmd
    push    {r0, r3}           @ save dx, dy
    cmp     r1, #1
    bne     vdg_draw
    pop     {r0, r1}
    bl      dv_move_to
    b       vdg_loop
vdg_draw:
    pop     {r0, r1}
    bl      dv_draw_delta
    b       vdg_loop
vdg_done:
    str     r10, [r8]           @ update PRINT_BEAM_X
    str     r11, [r9]           @ update PRINT_BEAM_Y
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpy_print_number(r0=x, r1=y, r2=value) — range -9999..9999, no leading zeros
.global vpy_print_number
.type vpy_print_number, %function
.thumb_func
vpy_print_number:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    sub     sp, sp, #8
    mov     r7, sp
    mov     r8, r7
    cmp     r6, #0
    bge     vpn_pos
    mov     r0, #45
    strb    r0, [r8]
    add     r8, r8, #1
    neg     r6, r6
vpn_pos:
    ldr     r0, =9999
    cmp     r6, r0
    ble     vpn_clamp
    mov     r6, r0
vpn_clamp:
    mov     r9, #0
    ldr     r0, =1000
    sdiv    r1, r6, r0
    mul     r0, r0, r1
    sub     r6, r6, r0
    cmp     r1, #0
    beq     vpn_skip_thou
    add     r1, r1, #48
    strb    r1, [r8]
    add     r8, r8, #1
    mov     r9, #1
vpn_skip_thou:
    mov     r0, #100
    sdiv    r1, r6, r0
    mul     r0, r0, r1
    sub     r6, r6, r0
    cmp     r9, #0
    bne     vpn_write_hund
    cmp     r1, #0
    beq     vpn_skip_hund
vpn_write_hund:
    add     r1, r1, #48
    strb    r1, [r8]
    add     r8, r8, #1
    mov     r9, #1
vpn_skip_hund:
    mov     r0, #10
    sdiv    r1, r6, r0
    mul     r0, r0, r1
    sub     r6, r6, r0
    cmp     r9, #0
    bne     vpn_write_tens
    cmp     r1, #0
    beq     vpn_skip_tens
vpn_write_tens:
    add     r1, r1, #48
    strb    r1, [r8]
    add     r8, r8, #1
vpn_skip_tens:
    add     r1, r6, #48
    strb    r1, [r8]
    add     r8, r8, #1
    mov     r0, #0
    strb    r0, [r8]
    mov     r0, r4
    mov     r1, r5
    mov     r2, r7
    bl      vpy_print_text
    add     sp, sp, #8
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

