@ psg_write(r0=reg, r1=data) — write AY-3-8912 PSG register
.global psg_write
.type psg_write, %function
.thumb_func
psg_write:
    push    {r4, r5, lr}
    mov     r4, r0              @ reg
    mov     r5, r1              @ data
    mov     r0, #0xD001
    mov     r1, r4
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x19
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD001
    mov     r1, r5
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x11
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    pop     {r4, r5, pc}
    .ltorg

@ psg_read(r0=reg) → r0 = PSG register value
.global psg_read
.type psg_read, %function
.thumb_func
psg_read:
    push    {r4, lr}
    mov     r4, r0              @ reg
    mov     r0, #0xD001
    mov     r1, r4
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x19
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD003
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD000
    mov     r1, #0x09
    bl      bus_write
    mov     r0, #0xD001
    bl      bus_read
    push    {r0}               @ save result
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD003
    mov     r1, #0xFF
    bl      bus_write
    pop     {r0}               @ return value
    pop     {r4, pc}
    .ltorg

@ vpy_update_buttons() — cache buttons and joystick axes (safe: called in WAIT_RECAL window)
.global vpy_update_buttons
.type vpy_update_buttons, %function
.thumb_func
vpy_update_buttons:
    push    {r4, lr}
    mov     r0, #0xD002
    mov     r1, #0x0F
    bl      bus_write
    mov     r0, #0xD000
    bl      bus_read
    ldr     r1, =BTN_STATE_J1
    str     r0, [r1]
    mov     r0, #0xD002
    mov     r1, #0xFF
    bl      bus_write
    mov     r0, #14
    bl      psg_read
    ldr     r1, =BTN_STATE_J2
    str     r0, [r1]
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    mov     r0, #0xD001
    bl      bus_read
    sxtb    r4, r0
    ldr     r0, =J1_AXIS_X
    str     r4, [r0]
    mov     r0, #0xD000
    mov     r1, #0x03
    bl      bus_write
    mov     r0, #0xD001
    bl      bus_read
    sxtb    r4, r0
    ldr     r0, =J1_AXIS_Y
    str     r4, [r0]
    mov     r0, #0xD000
    mov     r1, #0x00
    bl      bus_write
    mov     r0, #0xD001
    bl      bus_read
    sxtb    r4, r0
    ldr     r0, =J2_AXIS_X
    str     r4, [r0]
    mov     r0, #0xD000
    mov     r1, #0x02
    bl      bus_write
    mov     r0, #0xD001
    bl      bus_read
    sxtb    r4, r0
    ldr     r0, =J2_AXIS_Y
    str     r4, [r0]
    mov     r0, #0xD000
    mov     r1, #0x01
    bl      bus_write
    pop     {r4, pc}
    .ltorg

