@ vpy_sqrt(r0=n) → r0 = floor(sqrt(n))
.global vpy_sqrt
.type vpy_sqrt, %function
.thumb_func
vpy_sqrt:
    cmp     r0, #0
    beq     vsqrt_zero
    push    {r4, r5, r6}
    mov     r4, r0              @ n
    mov     r5, #0              @ lo
    ldr     r6, =46340         @ hi (floor(sqrt(2^31-1)))
    cmp     r4, r6
    blt     vsqrt_loop
    mov     r0, r6
    pop     {r4, r5, r6}
    bx      lr
vsqrt_loop:
    add     r0, r5, r6
    lsr     r0, r0, #1  @ mid = (lo+hi)/2
    mul     r2, r0, r0           @ mid*mid
    cmp     r2, r4
    beq     vsqrt_exact
    bgt     vsqrt_high
    mov     r5, r0
    add     r5, r5, #1
    cmp     r5, r6
    blt     vsqrt_loop
    b       vsqrt_done
vsqrt_high:
    mov     r6, r0
    cmp     r5, r6
    blt     vsqrt_loop
vsqrt_done:
    mov     r0, r5
    sub     r0, r0, #1
    pop     {r4, r5, r6}
    bx      lr
vsqrt_exact:
    pop     {r4, r5, r6}
    bx      lr
vsqrt_zero:
    bx      lr
    .ltorg

@ vpy_rand() → r0 = pseudo-random 0-32767 (LCG)
.global vpy_rand
.type vpy_rand, %function
.thumb_func
vpy_rand:
    push    {r4, r5, lr}
    ldr     r4, =RAND_SEED
    ldr     r0, [r4]
    ldr     r5, =1664525
    mul     r0, r0, r5
    ldr     r5, =1013904223
    add     r0, r0, r5
    str     r0, [r4]            @ save seed
    lsr     r0, r0, #16
    bic     r0, r0, #0x8000      @ clear bit15 (0x8000 is valid Thumb2 immediate)
    pop     {r4, r5, pc}
    .ltorg

@ vpy_rand_range(r0=lo, r1=hi) → r0 = random in [lo, hi]
.global vpy_rand_range
.type vpy_rand_range, %function
.thumb_func
vpy_rand_range:
    push    {r4, r5, lr}
    mov     r4, r0              @ lo
    sub     r5, r1, r0
    add     r5, r5, #1
    bl      vpy_rand
    sdiv    r1, r0, r5
    mul     r1, r1, r5
    sub     r0, r0, r1
    add     r0, r0, r4          @ + lo
    pop     {r4, r5, pc}
    .ltorg

