    beq.w   vglw_null
    ldrsh   r1, [r0, #2]              @ xMax
    ldrsh   r0, [r0, #0]              @ xMin
    sub     r0, r1, r0
    bx      lr
vglw_null:
    mov     r0, #0
    bx      lr
    .ltorg

@ vpy_get_level_height() -> r0
.global vpy_get_level_height
.type vpy_get_level_height, %function
