@ vpy_draw_anim(r0=anim_ptr, r1=ox, r2=oy, r3=state_ptr, r4=mirror)
.global vpy_draw_anim
.type vpy_draw_anim, %function
.thumb_func
vpy_draw_anim:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, r12, lr}
    mov     r12, r4                     @ save mirror before r4 overwritten
    mov     r4, r0                      @ anim header ptr
    mov     r10, r1                     @ save ox
    mov     r11, r2                     @ save oy
    mov     r5, r3                      @ state_ptr from caller
    ldrb    r6, [r5]                    @ frame_idx
    ldrb    r7, [r5, #1]                @ ticks_left (0=uninitialized)
    ldrb    r8, [r4, #2]                @ base_ref_count
    cmp     r8, #0
    beq     dar_tick
    add     r9, r4, #4                  @ first base_ref word-ptr
dar_base_loop:
    push    {r8, r9}
    sub     sp, sp, #8                  @ intensity slot + align
    mov     r0, #127
    str     r0, [sp]                    @ intensity = 127
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    mov     r3, r12                     @ mirror
    bl      vpy_draw_vector_ex
    add     sp, sp, #8
    pop     {r8, r9}
    add     r9, r9, #4
    subs    r8, r8, #1
    bne     dar_base_loop
dar_tick:
    cmp     r7, #0
    beq     dar_init_frame
    subs    r7, r7, #1
    bgt     dar_draw
    ldrb    r8, [r4]                    @ frame_count
    add     r6, r6, #1
    cmp     r6, r8
    blt     dar_no_wrap
    ldrb    r9, [r4, #1]                @ loop flag
    cmp     r9, #0
    beq     dar_freeze
    mov     r6, #0
dar_no_wrap:
    strb    r6, [r5]
dar_init_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2                  @ frame_idx * 4
    add     r9, r9, r8
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
    ldrb    r7, [r9]                    @ duration_ticks
    cmp     r7, #0
    it      le
    movle   r7, #1
    strb    r7, [r5, #1]
    b       dar_draw_vecs
dar_freeze:
    sub     r6, r6, #1
    strb    r6, [r5]
    mov     r7, #1
    strb    r7, [r5, #1]
    b       dar_draw_frame
dar_draw:
    strb    r7, [r5, #1]
dar_draw_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2
    add     r9, r9, r8
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
dar_draw_vecs:
    ldrb    r8, [r9, #1]                @ vec_ref_count
    cmp     r8, #0
    beq     dar_done
    add     r9, r9, #4                  @ skip duration+count+2-byte pad
    mov     r6, r8
dar_vec_loop:
    push    {r6, r9}
    sub     sp, sp, #8                  @ intensity slot + align
    mov     r0, #127
    str     r0, [sp]                    @ intensity = 127
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    mov     r3, r12                     @ mirror
    bl      vpy_draw_vector_ex
    add     sp, sp, #8
    pop     {r6, r9}
    add     r9, r9, #4
    subs    r6, r6, #1
    bne     dar_vec_loop
dar_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, r12, pc}
    .ltorg

